#
# Mapfile (version 2) for the static programs the illumos link-editor
# links: their data is not executable, which the link-editor's default
# for amd64 data allows.
#

$mapfile_version 2

LOAD_SEGMENT data {
	FLAGS = READ WRITE;
};
